CREATE OR REPLACE FUNCTION public.anonymize_contact(p_contact_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_owner_id uuid;
  v_sales_preserved integer := 0;
  v_tasks_deleted integer := 0;
  v_tasks_scrubbed integer := 0;
  v_partners_unlinked integer := 0;
  v_templates_archived integer := 0;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if not public.has_app_entitlement(v_user_id) then
    raise exception using errcode = '42501', message = 'app_entitlement_required';
  end if;
  if p_contact_id is null then
    raise exception using errcode = '22023', message = 'contact_id_required';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('zynergia_partner_graph', 0)
  );

  select user_id
    into v_owner_id
    from public.contacts
   where id = p_contact_id
   for update;

  -- Repeating a completed deletion is a harmless no-op. An existing contact
  -- owned by someone else is rejected explicitly below.
  if not found then
    return jsonb_build_object(
      'status', 'already_removed',
      'contact_id', p_contact_id
    );
  end if;
  if v_owner_id <> v_user_id then
    raise exception using errcode = '42501', message = 'contact_not_owned';
  end if;

  -- Keep aggregate sales history but remove the personal link.
  update public.sales
     set contact_id = null
   where user_id = v_user_id
     and contact_id = p_contact_id;
  get diagnostics v_sales_preserved = row_count;

  -- Every unfinished task is future work, even when its due date has passed.
  delete from public.tasks
   where user_id = v_user_id
     and contact_id = p_contact_id
     and not coalesce(completed, false);
  get diagnostics v_tasks_deleted = row_count;

  -- Preserve completed task counts without retaining the contact identifier or
  -- a free-text task name that may contain the person's name.
  update public.tasks
     set contact_id = null,
         task_name = case
           when task_name is null then null
           else 'Seguimiento de contacto eliminado'
         end
   where user_id = v_user_id
     and contact_id = p_contact_id;
  get diagnostics v_tasks_scrubbed = row_count;

  -- This migration runs before message_templates is created. Dynamic SQL keeps
  -- the function installable now and archives contact-specific templates once
  -- that table exists, without retaining the deleted relationship.
  if pg_catalog.to_regclass('public.message_templates') is not null then
    execute
      'update public.message_templates '
      || 'set contact_id = null, archived_at = coalesce(archived_at, pg_catalog.now()) '
      || 'where user_id = $1 and contact_id = $2'
      using v_user_id, p_contact_id;
    get diagnostics v_templates_archived = row_count;
  end if;

  -- A linked account must not keep pointing at a leader after its relationship
  -- contact is removed.
  update public.settings child
     set parent_id = null
   where child.parent_id = v_user_id
     and exists (
       select 1
         from public.partners relationship
        where relationship.user_id = v_user_id
          and relationship.contact_id = p_contact_id
          and relationship.partner_user_id = child.user_id
     );

  delete from public.partners
   where user_id = v_user_id
     and contact_id = p_contact_id;
  get diagnostics v_partners_unlinked = row_count;

  delete from public.contacts
   where id = p_contact_id
     and user_id = v_user_id;

  return jsonb_build_object(
    'status', 'anonymized',
    'contact_id', p_contact_id,
    'sales_preserved', v_sales_preserved,
    'tasks_deleted', v_tasks_deleted,
    'tasks_scrubbed', v_tasks_scrubbed,
    'templates_archived', v_templates_archived,
    'partners_unlinked', v_partners_unlinked
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.assert_stripe_connect_checkout_ready()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if exists (
    select 1
      from public.stripe_connect_charges
     where reconciliation_status <> 'balanced'
  ) or exists (
    select 1
      from public.stripe_connect_anomalies
     where status = 'open'
  ) then
    raise exception 'stripe_connect_ledger_unhealthy';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.begin_account_deletion(p_user_id uuid, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request public.account_deletion_requests%rowtype;
  v_account public.billing_accounts%rowtype;
  v_execute_at timestamptz;
  v_should_schedule boolean := false;
begin
  if p_user_id is null or p_operation_id is null then
    raise exception 'invalid_deletion_request';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_user_id::text, 1)
  );

  select *
    into v_request
    from public.account_deletion_requests
   where user_id = p_user_id
   for update;

  if not found then
    if exists (
      select 1 from public.account_deletion_requests
       where operation_id = p_operation_id and user_id is distinct from p_user_id
    ) then
      raise exception 'operation_id_already_used';
    end if;
    insert into public.account_deletion_requests (operation_id, user_id)
    values (p_operation_id, p_user_id)
    returning * into v_request;
  elsif v_request.status = 'processing'
        and v_request.execute_at <= now()
        and v_request.locked_at > now() - interval '15 minutes' then
    return jsonb_build_object(
      'request_id', v_request.id,
      'status', v_request.status,
      'operation_id', v_request.operation_id,
      'user_id', v_request.user_id,
      'stripe_customer_id', v_request.stripe_customer_id,
      'stripe_subscription_id', v_request.stripe_subscription_id,
      'execute_at', v_request.execute_at,
      'should_schedule', false,
      'already_processing', true
    );
  end if;

  select *
    into v_account
    from public.billing_accounts
   where user_id = p_user_id and anonymized_at is null;

  if v_account.id is not null
     and v_account.entitlement_eligible
     and v_account.subscription_status = 'active'
     and v_account.access_blocked_reason is null
     and v_account.current_period_end is not null
     and v_account.current_period_end > now() then
    v_execute_at := v_account.current_period_end;
    v_should_schedule := true;
  else
    v_execute_at := now();
  end if;

  update public.account_deletion_requests
     set status = case when v_should_schedule then 'scheduling' else 'processing' end,
         execute_at = v_execute_at,
         stripe_customer_id = v_account.stripe_customer_id,
         stripe_subscription_id = v_account.stripe_subscription_id,
         attempt_count = attempt_count + 1,
         locked_at = now(),
         failure_code = null
   where id = v_request.id
   returning * into v_request;

  return jsonb_build_object(
    'request_id', v_request.id,
    'status', v_request.status,
    'operation_id', v_request.operation_id,
    'user_id', v_request.user_id,
    'stripe_customer_id', v_request.stripe_customer_id,
    'stripe_subscription_id', v_request.stripe_subscription_id,
    'execute_at', v_request.execute_at,
    'should_schedule', v_should_schedule
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_billing_account(p_user_id uuid, p_email text, p_expected_stripe_customer_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_email text := nullif(lower(btrim(p_email)), '');
  v_account public.billing_accounts%rowtype;
begin
  if v_email is null then
    raise exception 'verified_email_required';
  end if;
  if p_user_id is null or not exists (
    select 1
      from auth.users
     where id = p_user_id
       and lower(email) = v_email
       and email_confirmed_at is not null
  ) then
    raise exception 'invalid_user';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_email, 0));

  select *
    into v_account
    from public.billing_accounts
   where user_id = p_user_id
     and anonymized_at is null
   for update;

  if found then
    if not v_account.entitlement_eligible
       and v_account.subscription_status in ('active', 'trialing', 'past_due', 'unpaid', 'paused', 'incomplete') then
      return jsonb_build_object('status', 'conflict', 'reason', 'unsupported_price');
    end if;
    return jsonb_build_object(
      'status', 'existing',
      'stripe_customer_id', v_account.stripe_customer_id,
      'stripe_subscription_id', v_account.stripe_subscription_id
    );
  end if;

  if p_expected_stripe_customer_id is null then
    return jsonb_build_object('status', 'validation_required');
  end if;
  if p_expected_stripe_customer_id !~ '^cus_' then
    raise exception 'invalid_expected_stripe_customer_id';
  end if;

  select *
    into v_account
    from public.billing_accounts
   where stripe_customer_id = p_expected_stripe_customer_id
   for update;

  if not found or v_account.anonymized_at is not null then
    return jsonb_build_object('status', 'not_found');
  end if;
  if v_account.user_id is not null then
    return jsonb_build_object('status', 'conflict', 'reason', 'billing_account_already_owned');
  end if;
  if v_account.claim_email is distinct from v_email then
    return jsonb_build_object('status', 'conflict', 'reason', 'validated_customer_email_mismatch');
  end if;
  if not v_account.entitlement_eligible
     and v_account.subscription_status in ('active', 'trialing', 'past_due', 'unpaid', 'paused', 'incomplete') then
    return jsonb_build_object('status', 'conflict', 'reason', 'unsupported_price');
  end if;

  update public.billing_accounts
     set user_id = p_user_id,
         claim_email = null
   where id = v_account.id
     and user_id is null
   returning * into v_account;

  if not found then
    return jsonb_build_object('status', 'conflict', 'reason', 'billing_claim_race');
  end if;

  perform public.refresh_stripe_access_grant(v_account.stripe_customer_id);

  return jsonb_build_object(
    'status', 'claimed',
    'stripe_customer_id', v_account.stripe_customer_id,
    'stripe_subscription_id', v_account.stripe_subscription_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_stripe_webhook_event(p_event_id text, p_event_type text, p_event_created_at timestamp with time zone, p_payload_sha256 text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rows integer;
  v_existing_hash text;
begin
  if p_event_id is null or p_payload_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'invalid_webhook_event';
  end if;

  insert into public.stripe_webhook_events (
    event_id, event_type, event_created_at, payload_sha256
  ) values (
    p_event_id, p_event_type, p_event_created_at, p_payload_sha256
  )
  on conflict (event_id) do nothing;
  get diagnostics v_rows = row_count;
  if v_rows = 1 then
    return true;
  end if;

  select payload_sha256
    into v_existing_hash
    from public.stripe_webhook_events
   where event_id = p_event_id;
  if v_existing_hash is distinct from p_payload_sha256 then
    raise exception 'webhook_event_hash_mismatch';
  end if;

  update public.stripe_webhook_events
     set status = 'processing',
         attempt_count = attempt_count + 1,
         locked_at = now(),
         processed_at = null,
         last_error = null
   where event_id = p_event_id
     and (
       status = 'failed'
       or (status = 'processing' and locked_at < now() - interval '5 minutes')
     );
  get diagnostics v_rows = row_count;
  return v_rows = 1;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_onboarding()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_completed_at timestamptz := now();
  v_rows integer;
begin
  if v_user_id is null then
    raise exception 'authentication_required';
  end if;
  if not public.has_app_entitlement(v_user_id) then
    raise exception 'app_entitlement_required';
  end if;

  update public.settings
     set onboarding_completed_at = coalesce(onboarding_completed_at, v_completed_at)
   where user_id = v_user_id;
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    raise exception 'settings_row_missing';
  end if;

  select onboarding_completed_at
    into v_completed_at
    from public.settings
   where user_id = v_user_id;
  return v_completed_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_stripe_connect_reconciliation(p_stripe_charge_id text, p_net_clawback_amount bigint, p_event_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_charge public.stripe_connect_charges%rowtype;
  v_state jsonb;
begin
  select * into v_charge
    from public.stripe_connect_charges
   where stripe_charge_id = p_stripe_charge_id
   for update;
  if not found then raise exception 'connect_charge_missing'; end if;
  v_state := public.get_stripe_connect_charge_state(p_stripe_charge_id);
  if (v_state->>'net_clawback_amount')::bigint <> p_net_clawback_amount
     or p_net_clawback_amount <> v_charge.desired_clawback_amount then
    raise exception 'connect_reconciliation_not_balanced';
  end if;
  update public.stripe_connect_charges
     set reconciled_net_clawback_amount = p_net_clawback_amount,
         reconciliation_status = 'balanced',
         reconciled_at = now(),
         last_error = null,
         last_event_id = p_event_id
   where stripe_charge_id = p_stripe_charge_id;
  return public.get_stripe_connect_charge_state(p_stripe_charge_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.delete_user_data(p_request_id uuid, p_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_request public.account_deletion_requests%rowtype;
  v_table text;
begin
  select *
    into v_request
    from public.account_deletion_requests
   where id = p_request_id
   for update;

  if not found or v_request.user_id is distinct from p_user_id then
    raise exception 'invalid_deletion_request';
  end if;
  if v_request.status = 'completed' then
    return;
  end if;

  if to_regclass('public.partners') is not null
     and exists (
       select 1 from information_schema.columns
        where table_schema = 'public' and table_name = 'partners' and column_name = 'partner_user_id'
     ) then
    execute 'update public.partners set partner_user_id = null where partner_user_id = $1'
      using p_user_id;
  end if;

  if to_regclass('public.settings') is not null
     and exists (
       select 1 from information_schema.columns
        where table_schema = 'public' and table_name = 'settings' and column_name = 'parent_id'
     ) then
    execute 'update public.settings set parent_id = null where parent_id = $1'
      using p_user_id;
  end if;

  foreach v_table in array array[
    'tasks', 'sales', 'partners', 'contacts', 'tags', 'product_links',
    'user_templates', 'user_products', 'message_templates', 'notifications', 'settings'
  ] loop
    if to_regclass('public.' || v_table) is not null
       and exists (
         select 1 from information_schema.columns
          where table_schema = 'public' and table_name = v_table and column_name = 'user_id'
       ) then
      execute format('delete from public.%I where user_id = $1', v_table)
        using p_user_id;
    end if;
  end loop;

  delete from public.access_grants where user_id = p_user_id;
  update public.billing_accounts
     set user_id = null,
         claim_email = null,
         operation_id = null,
         operation_expires_at = null,
         anonymized_at = coalesce(anonymized_at, now())
   where user_id = p_user_id;

  update public.account_deletion_requests
     set status = 'data_deleted', failure_code = null
   where id = p_request_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_partner_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_code text;
  v_attempt integer;
begin
  if auth.uid() is null then
    raise exception 'authentication_required';
  end if;
  if not public.has_app_entitlement(auth.uid()) then
    raise exception 'app_entitlement_required';
  end if;

  select partner_code
    into v_code
    from public.settings
   where user_id = auth.uid()
   for update;
  if not found then
    raise exception 'settings_row_missing';
  end if;
  if v_code is not null then
    return v_code;
  end if;

  for v_attempt in 1..8 loop
    v_code := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
    begin
      update public.settings
         set partner_code = v_code
       where user_id = auth.uid()
         and partner_code is null;
      return v_code;
    exception when unique_violation then
      -- A collision is harmless; generate another opaque code.
    end;
  end loop;

  raise exception 'partner_code_generation_failed';
end;
$function$

CREATE OR REPLACE FUNCTION public.get_partner_partners_count(p_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_count integer;
begin
  if auth.uid() is null or not (
    p_user_id = auth.uid()
    or exists (
      select 1
        from public.partners relationship
       where relationship.user_id = auth.uid()
         and relationship.partner_user_id = p_user_id
    )
  ) then
    raise exception 'partner_access_denied';
  end if;
  if not public.has_app_entitlement(auth.uid()) then
    raise exception 'app_entitlement_required';
  end if;

  select count(*)::integer
    into v_count
    from public.partners p
   where p.user_id = p_user_id;
  return v_count;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_partner_sales_data(p_user_id uuid)
 RETURNS TABLE(product_id text, contact_id uuid, status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not (
    p_user_id = auth.uid()
    or exists (
      select 1
        from public.partners relationship
       where relationship.user_id = auth.uid()
         and relationship.partner_user_id = p_user_id
    )
  ) then
    raise exception 'partner_access_denied';
  end if;
  if not public.has_app_entitlement(auth.uid()) then
    raise exception 'app_entitlement_required';
  end if;

  return query
  select s.product_id, s.contact_id, coalesce(s.status, 'active')
    from public.sales s
   where s.user_id = p_user_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_partner_stats(p_user_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result json;
begin
  if auth.uid() is null or not (
    p_user_id = auth.uid()
    or exists (
      select 1
        from public.partners relationship
       where relationship.user_id = auth.uid()
         and relationship.partner_user_id = p_user_id
    )
  ) then
    raise exception 'partner_access_denied';
  end if;
  if not public.has_app_entitlement(auth.uid()) then
    raise exception 'app_entitlement_required';
  end if;

  select json_build_object(
    'clients', (select count(*) from public.contacts where user_id = p_user_id and contact_type = 'cliente_producto'),
    'active_sales', (select count(*) from public.sales where user_id = p_user_id and coalesce(status, 'active') = 'active'),
    'partners', (select count(*) from public.partners where user_id = p_user_id),
    'active_partners', (select count(*) from public.partners where user_id = p_user_id and fast_start_status = 'activo'),
    'tasks_done', (select count(*) from public.tasks where user_id = p_user_id and completed is true)
  ) into v_result;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_partners_activity(user_ids uuid[])
 RETURNS TABLE(user_id uuid, last_active timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then
    raise exception 'authentication_required';
  end if;
  if not public.has_app_entitlement(auth.uid()) then
    raise exception 'app_entitlement_required';
  end if;
  if exists (
    select 1
      from unnest(coalesce(user_ids, array[]::uuid[])) requested(user_id)
     where requested.user_id <> auth.uid()
       and not exists (
         select 1
           from public.partners relationship
          where relationship.user_id = auth.uid()
            and relationship.partner_user_id = requested.user_id
       )
  ) then
    raise exception 'partner_access_denied';
  end if;

  return query
  select s.user_id, s.last_active
    from public.settings s
   where s.user_id = any(coalesce(user_ids, array[]::uuid[]));
end;
$function$

CREATE OR REPLACE FUNCTION public.get_stripe_connect_charge_state(p_stripe_charge_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_charge public.stripe_connect_charges%rowtype;
  v_transfers jsonb;
  v_forward bigint;
  v_reversed bigint;
  v_net bigint;
begin
  select * into v_charge
    from public.stripe_connect_charges
   where stripe_charge_id = p_stripe_charge_id;
  if not found then
    return null;
  end if;

  select coalesce(jsonb_agg(to_jsonb(t) order by
           case when t.kind = 'restoration' then 0 else 1 end,
           t.stripe_created_at desc, t.stripe_transfer_id), '[]'::jsonb),
         coalesce(sum(t.amount), 0),
         coalesce(sum(t.amount_reversed), 0)
    into v_transfers, v_forward, v_reversed
    from public.stripe_connect_transfers t
   where t.stripe_charge_id = p_stripe_charge_id;

  v_net := v_charge.original_transfer_amount - (v_forward - v_reversed);
  return jsonb_build_object(
    'charge', to_jsonb(v_charge),
    'transfers', v_transfers,
    'forward_amount', v_forward,
    'reversed_amount', v_reversed,
    'net_clawback_amount', v_net
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.import_partner_clients(p_partner_user_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  imported INTEGER := 0;
  r RECORD;
  caller_id UUID := auth.uid();
BEGIN
  FOR r IN 
    SELECT * FROM contacts 
    WHERE user_id = p_partner_user_id AND contact_type = 'cliente_producto'
  LOOP
    INSERT INTO contacts (user_id, full_name, phone, country_code, notes, contact_type, tag_ids)
    VALUES (caller_id, r.full_name, r.phone, r.country_code, r.notes, 'cliente_producto', r.tag_ids);
    imported := imported + 1;
  END LOOP;
  RETURN imported;
END;
$function$

CREATE OR REPLACE FUNCTION public.join_upline_by_code(p_code text)
 RETURNS TABLE(upline_user_id uuid, upline_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_child public.settings%rowtype;
  v_upline public.settings%rowtype;
  v_existing_owner uuid;
  v_existing_partner_id uuid;
  v_contact_id uuid;
begin
  if auth.uid() is null then
    raise exception 'authentication_required';
  end if;
  if not public.has_app_entitlement(auth.uid()) then
    raise exception 'app_entitlement_required';
  end if;
  if nullif(btrim(p_code), '') is null or btrim(p_code) !~ '^[A-Za-z0-9]{4,8}$' then
    raise exception 'invalid_partner_code';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('zynergia_partner_graph', 0)
  );

  select * into v_child
    from public.settings
   where user_id = auth.uid()
   for update;
  if not found then
    raise exception 'settings_row_missing';
  end if;

  select * into v_upline
    from public.settings
   where upper(partner_code) = upper(btrim(p_code))
   for update;
  if not found then
    raise exception 'partner_code_not_found';
  end if;
  if v_upline.user_id = auth.uid() then
    raise exception 'self_link_not_allowed';
  end if;
  if v_child.parent_id is not null and v_child.parent_id <> v_upline.user_id then
    raise exception 'partner_already_linked';
  end if;

  select p.user_id, p.id
    into v_existing_owner, v_existing_partner_id
    from public.partners p
   where p.partner_user_id = auth.uid()
   for update;
  if found and v_existing_owner <> v_upline.user_id then
    raise exception 'partner_already_linked';
  end if;

  if exists (
    with recursive ancestors(user_id, parent_id) as (
      select s.user_id, s.parent_id
        from public.settings s
       where s.user_id = v_upline.user_id
      union
      select parent.user_id, parent.parent_id
        from public.settings parent
        join ancestors child on parent.user_id = child.parent_id
       where child.parent_id is not null
    )
    select 1 from ancestors where user_id = auth.uid()
  ) then
    raise exception 'partner_cycle_detected';
  end if;

  if v_existing_partner_id is null then
    insert into public.contacts (
      user_id, full_name, contact_type, phone, country_code, notes
    ) values (
      v_upline.user_id,
      coalesce(nullif(btrim(v_child.user_name), ''), 'Partner'),
      'partner', '', '+52', 'Agregado por código de invitación'
    ) returning id into v_contact_id;

    insert into public.partners (
      user_id, contact_id, partner_user_id, start_date, fast_start_deadline,
      fast_start_status, fase_actual, qteam_completed, fs_level1_completed,
      fs_level2_completed, xteam_completed
    ) values (
      v_upline.user_id, v_contact_id, auth.uid(), current_date, current_date + 120,
      'activo', 1, false, false, false, false
    );
  end if;

  update public.settings
     set parent_id = v_upline.user_id
   where user_id = auth.uid()
     and (parent_id is null or parent_id = v_upline.user_id);
  if not found then
    raise exception 'partner_already_linked';
  end if;

  return query
  select v_upline.user_id,
         coalesce(nullif(btrim(v_upline.user_name), ''), 'Líder');
end;
$function$

CREATE OR REPLACE FUNCTION public.link_existing_partner_by_code(p_partner_id uuid, p_code text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_target public.settings%rowtype;
  v_current_partner_user_id uuid;
begin
  if auth.uid() is null then
    raise exception 'authentication_required';
  end if;
  if not public.has_app_entitlement(auth.uid()) then
    raise exception 'app_entitlement_required';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('zynergia_partner_graph', 0)
  );

  select p.partner_user_id
    into v_current_partner_user_id
    from public.partners p
   where p.id = p_partner_id and p.user_id = auth.uid()
   for update;
  if not found then
    raise exception 'partner_not_found';
  end if;

  select * into v_target
    from public.settings
   where upper(partner_code) = upper(btrim(p_code))
   for update;
  if not found then
    raise exception 'partner_code_not_found';
  end if;
  if v_target.user_id = auth.uid() then
    raise exception 'self_link_not_allowed';
  end if;
  if v_current_partner_user_id is not null and v_current_partner_user_id <> v_target.user_id then
    raise exception 'partner_record_already_linked';
  end if;
  if v_target.parent_id is not null and v_target.parent_id <> auth.uid() then
    raise exception 'partner_already_linked';
  end if;
  if exists (
    with recursive ancestors(user_id, parent_id) as (
      select s.user_id, s.parent_id from public.settings s where s.user_id = auth.uid()
      union
      select parent.user_id, parent.parent_id
        from public.settings parent
        join ancestors child on parent.user_id = child.parent_id
       where child.parent_id is not null
    )
    select 1 from ancestors where user_id = v_target.user_id
  ) then
    raise exception 'partner_cycle_detected';
  end if;
  if exists (
    select 1 from public.partners p
     where p.partner_user_id = v_target.user_id
       and p.id <> p_partner_id
  ) then
    raise exception 'partner_duplicate_link';
  end if;

  update public.partners
     set partner_user_id = v_target.user_id
   where id = p_partner_id and user_id = auth.uid();
  update public.settings
     set parent_id = auth.uid()
   where user_id = v_target.user_id
     and (parent_id is null or parent_id = auth.uid());
  return v_target.user_id;
end;
$function$

