CREATE OR REPLACE FUNCTION public.reconcile_stripe_access_incident_canonical(p_stripe_customer_id text, p_stripe_subscription_id text, p_claim_email text, p_incident_key text, p_incident_kind text, p_access_blocked_reason text, p_event_id text, p_event_created_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_account public.billing_accounts%rowtype;
  v_email text := nullif(lower(btrim(p_claim_email)), '');
  v_status text := case when p_access_blocked_reason is null then 'resolved' else 'blocking' end;
begin
  if p_stripe_customer_id !~ '^cus_' or p_stripe_subscription_id !~ '^sub_'
     or p_event_id is null or btrim(p_event_id) = '' or p_event_created_at is null
     or p_incident_kind not in ('full_refund', 'dispute')
     or (p_incident_kind = 'full_refund' and p_incident_key !~ '^charge:ch_')
     or (p_incident_kind = 'dispute' and p_incident_key !~ '^dispute:(dp_|du_)')
     or (p_incident_kind = 'full_refund' and p_access_blocked_reason is not null
         and p_access_blocked_reason <> 'full_refund')
     or (p_incident_kind = 'dispute' and p_access_blocked_reason is not null
         and p_access_blocked_reason not in ('dispute_open', 'dispute_lost')) then
    raise exception 'invalid_canonical_access_incident';
  end if;

  insert into public.billing_accounts (
    stripe_customer_id, stripe_subscription_id, claim_email
  ) values (
    p_stripe_customer_id, p_stripe_subscription_id, v_email
  ) on conflict (stripe_customer_id) do nothing;

  select * into v_account
    from public.billing_accounts
   where stripe_customer_id = p_stripe_customer_id
   for update;
  if v_account.anonymized_at is not null then
    return jsonb_build_object('status', 'ignored_anonymized');
  end if;
  if v_status = 'blocking' and v_account.stripe_subscription_id is not null
     and v_account.stripe_subscription_id <> p_stripe_subscription_id then
    return jsonb_build_object('status', 'ignored_unrelated_subscription');
  end if;

  update public.billing_accounts
     set stripe_subscription_id = coalesce(stripe_subscription_id, p_stripe_subscription_id),
         claim_email = case when user_id is null then coalesce(claim_email, v_email) else null end,
         access_decision_event_id = case
           when access_decision_at is null or p_event_created_at >= access_decision_at
             then p_event_id
           else access_decision_event_id
         end,
         access_decision_at = greatest(
           coalesce(access_decision_at, '-infinity'::timestamptz),
           p_event_created_at
         )
   where id = v_account.id;

  insert into public.stripe_access_incidents (
    stripe_customer_id, stripe_subscription_id, incident_key, incident_kind,
    status, blocked_reason, last_event_id, last_event_created_at, resolved_at
  ) values (
    p_stripe_customer_id, p_stripe_subscription_id, p_incident_key, p_incident_kind,
    v_status, p_access_blocked_reason, p_event_id, p_event_created_at,
    case when v_status = 'resolved' then now() else null end
  ) on conflict (stripe_customer_id, incident_key) do update
    set stripe_subscription_id = excluded.stripe_subscription_id,
        incident_kind = excluded.incident_kind,
        status = excluded.status,
        blocked_reason = excluded.blocked_reason,
        last_event_id = excluded.last_event_id,
        last_event_created_at = greatest(
          public.stripe_access_incidents.last_event_created_at,
          excluded.last_event_created_at
        ),
        resolved_at = excluded.resolved_at;

  perform public.refresh_stripe_access_block(p_stripe_customer_id);
  perform public.refresh_stripe_access_grant(p_stripe_customer_id);
  return jsonb_build_object('status', v_status, 'incident_key', p_incident_key);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_sale(p_operation_id uuid, p_contact_id uuid, p_product_id text, p_purchase_date date, p_sale_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_sale public.sales%rowtype;
  v_created boolean := false;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'authentication_required';
  end if;
  if not public.has_app_entitlement(v_user_id) then
    raise exception using errcode = '42501', message = 'app_entitlement_required';
  end if;
  if p_operation_id is null or p_contact_id is null or p_purchase_date is null then
    raise exception using errcode = '22023', message = 'sale_fields_required';
  end if;
  if nullif(btrim(p_product_id), '') is null then
    raise exception using errcode = '22023', message = 'product_required';
  end if;
  if p_sale_type not in ('nueva', 'recompra') then
    raise exception using errcode = '22023', message = 'invalid_sale_type';
  end if;

  perform 1
    from public.contacts
   where id = p_contact_id
     and user_id = v_user_id
   for key share;
  if not found then
    raise exception using errcode = '42501', message = 'contact_not_owned_or_missing';
  end if;

  -- A retry with the same operation must describe the same sale.
  select *
    into v_sale
    from public.sales
   where user_id = v_user_id
     and operation_id = p_operation_id;

  if found then
    if v_sale.contact_id is distinct from p_contact_id
       or v_sale.product_id is distinct from p_product_id
       or v_sale.purchase_date is distinct from p_purchase_date
       or v_sale.sale_type is distinct from p_sale_type then
      raise exception using errcode = '23505', message = 'operation_id_reused_with_different_sale';
    end if;
    return to_jsonb(v_sale) || jsonb_build_object('created', false);
  end if;

  insert into public.sales (
    user_id,
    contact_id,
    product_id,
    purchase_date,
    sale_type,
    status,
    operation_id
  ) values (
    v_user_id,
    p_contact_id,
    p_product_id,
    p_purchase_date,
    p_sale_type,
    'active',
    p_operation_id
  )
  on conflict (user_id, operation_id) where operation_id is not null
  do nothing
  returning * into v_sale;

  v_created := found;
  if not v_created then
    select *
      into v_sale
      from public.sales
     where user_id = v_user_id
       and operation_id = p_operation_id;
  end if;

  if v_sale.id is null then
    raise exception using errcode = '40001', message = 'sale_retry_required';
  end if;
  if v_sale.contact_id is distinct from p_contact_id
     or v_sale.product_id is distinct from p_product_id
     or v_sale.purchase_date is distinct from p_purchase_date
     or v_sale.sale_type is distinct from p_sale_type then
    raise exception using errcode = '23505', message = 'operation_id_reused_with_different_sale';
  end if;

  return to_jsonb(v_sale) || jsonb_build_object('created', v_created);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_stripe_access_incident(p_stripe_customer_id text, p_stripe_subscription_id text, p_claim_email text, p_incident_key text, p_incident_kind text, p_access_blocked_reason text, p_event_id text, p_event_created_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_account public.billing_accounts%rowtype;
  v_incident public.stripe_access_incidents%rowtype;
  v_email text := nullif(lower(btrim(p_claim_email)), '');
  v_status text := case when p_access_blocked_reason is null then 'resolved' else 'blocking' end;
begin
  if p_stripe_customer_id is null or p_stripe_customer_id !~ '^cus_'
     or p_stripe_subscription_id is null or p_stripe_subscription_id !~ '^sub_' then
    raise exception 'invalid_stripe_billing_target';
  end if;
  if p_event_id is null or btrim(p_event_id) = '' or p_event_created_at is null then
    raise exception 'invalid_access_incident_event';
  end if;
  if p_incident_kind not in ('full_refund', 'dispute')
     or (p_incident_kind = 'full_refund' and p_incident_key !~ '^charge:ch_')
     or (p_incident_kind = 'dispute' and p_incident_key !~ '^dispute:dp_') then
    raise exception 'invalid_access_incident';
  end if;
  if (p_incident_kind = 'full_refund' and p_access_blocked_reason is distinct from 'full_refund')
     or (p_incident_kind = 'dispute' and p_access_blocked_reason is not null
         and p_access_blocked_reason not in ('dispute_open', 'dispute_lost')) then
    raise exception 'invalid_access_blocked_reason';
  end if;

  insert into public.billing_accounts (
    stripe_customer_id, stripe_subscription_id, claim_email
  ) values (
    p_stripe_customer_id, p_stripe_subscription_id, v_email
  )
  on conflict (stripe_customer_id) do nothing;

  select *
    into v_account
    from public.billing_accounts
   where stripe_customer_id = p_stripe_customer_id
   for update;

  if v_account.anonymized_at is not null then
    return jsonb_build_object('status', 'ignored_anonymized');
  end if;
  if v_status = 'blocking'
     and v_account.stripe_subscription_id is not null
     and v_account.stripe_subscription_id <> p_stripe_subscription_id then
    return jsonb_build_object('status', 'ignored_unrelated_subscription');
  end if;
  if p_incident_kind = 'full_refund'
     and v_account.last_paid_invoice_event_at is not null
     and p_event_created_at < v_account.last_paid_invoice_event_at then
    return jsonb_build_object('status', 'ignored_before_latest_payment');
  end if;

  update public.billing_accounts
     set stripe_subscription_id = coalesce(stripe_subscription_id, p_stripe_subscription_id),
         claim_email = case
           when user_id is null then coalesce(claim_email, v_email)
           else null
         end
   where id = v_account.id;

  insert into public.stripe_access_incidents (
    stripe_customer_id,
    stripe_subscription_id,
    incident_key,
    incident_kind,
    status,
    blocked_reason,
    last_event_id,
    last_event_created_at,
    resolved_at
  ) values (
    p_stripe_customer_id,
    p_stripe_subscription_id,
    p_incident_key,
    p_incident_kind,
    v_status,
    p_access_blocked_reason,
    p_event_id,
    p_event_created_at,
    case when v_status = 'resolved' then p_event_created_at else null end
  )
  on conflict (stripe_customer_id, incident_key) do update
    set stripe_subscription_id = excluded.stripe_subscription_id,
        incident_kind = excluded.incident_kind,
        status = excluded.status,
        blocked_reason = excluded.blocked_reason,
        last_event_id = excluded.last_event_id,
        last_event_created_at = excluded.last_event_created_at,
        resolved_at = excluded.resolved_at
    where excluded.last_event_created_at > public.stripe_access_incidents.last_event_created_at
       or (
         excluded.last_event_created_at = public.stripe_access_incidents.last_event_created_at
         and excluded.status = 'blocking'
         and public.stripe_access_incidents.status = 'resolved'
       )
  returning * into v_incident;

  if v_incident.id is null then
    return jsonb_build_object('status', 'ignored_stale_event');
  end if;

  update public.billing_accounts
     set access_decision_event_id = case
           when access_decision_at is null or p_event_created_at >= access_decision_at
             then p_event_id
           else access_decision_event_id
         end,
         access_decision_at = greatest(
           coalesce(access_decision_at, '-infinity'::timestamptz),
           p_event_created_at
         )
   where stripe_customer_id = p_stripe_customer_id;

  perform public.refresh_stripe_access_block(p_stripe_customer_id);
  perform public.refresh_stripe_access_grant(p_stripe_customer_id);

  return jsonb_build_object('status', v_status, 'incident_key', p_incident_key);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_stripe_connect_restoration(p_operation_key text, p_stripe_charge_id text, p_stripe_transfer_id text, p_amount bigint, p_currency text, p_destination_account_id text, p_transfer_created_at timestamp with time zone, p_event_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_operation_key is null or length(p_operation_key) < 16
     or p_stripe_transfer_id !~ '^tr_' or p_amount <= 0
     or p_currency !~ '^[a-z]{3}$' or p_destination_account_id !~ '^acct_'
     or p_transfer_created_at is null or p_event_id is null then
    raise exception 'invalid_connect_restoration';
  end if;
  if exists (
    select 1 from public.stripe_connect_transfers
     where stripe_transfer_id = p_stripe_transfer_id
       and (
         stripe_charge_id is distinct from p_stripe_charge_id
         or kind <> 'restoration'
         or amount is distinct from p_amount
         or currency is distinct from p_currency
         or stripe_destination_account_id is distinct from p_destination_account_id
         or stripe_created_at is distinct from p_transfer_created_at
       )
  ) then
    raise exception 'connect_restoration_identity_conflict';
  end if;
  insert into public.stripe_connect_transfers (
    stripe_transfer_id, stripe_charge_id, kind, amount, amount_reversed,
    currency, stripe_destination_account_id, stripe_created_at, last_seen_at
  ) values (
    p_stripe_transfer_id, p_stripe_charge_id, 'restoration', p_amount, 0,
    p_currency, p_destination_account_id, p_transfer_created_at, now()
  ) on conflict (stripe_transfer_id) do nothing;

  insert into public.stripe_connect_adjustments (
    operation_key, stripe_charge_id, kind, source_transfer_id,
    stripe_object_id, amount, event_id
  ) values (
    p_operation_key, p_stripe_charge_id, 'restoration', null,
    p_stripe_transfer_id, p_amount, p_event_id
  ) on conflict do nothing;
  if not exists (
    select 1 from public.stripe_connect_adjustments
     where operation_key = p_operation_key
       and stripe_charge_id = p_stripe_charge_id
       and kind = 'restoration'
       and source_transfer_id is null
       and stripe_object_id = p_stripe_transfer_id
       and amount = p_amount
  ) then
    raise exception 'connect_restoration_idempotency_conflict';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_stripe_connect_reversal(p_operation_key text, p_stripe_charge_id text, p_source_transfer_id text, p_stripe_reversal_id text, p_amount bigint, p_event_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_operation_key is null or length(p_operation_key) < 16
     or p_source_transfer_id !~ '^tr_' or p_stripe_reversal_id !~ '^trr_'
     or p_amount <= 0 or p_event_id is null then
    raise exception 'invalid_connect_reversal';
  end if;
  insert into public.stripe_connect_adjustments (
    operation_key, stripe_charge_id, kind, source_transfer_id,
    stripe_object_id, amount, event_id
  ) values (
    p_operation_key, p_stripe_charge_id, 'reversal', p_source_transfer_id,
    p_stripe_reversal_id, p_amount, p_event_id
  ) on conflict do nothing;
  if not exists (
    select 1 from public.stripe_connect_adjustments
     where operation_key = p_operation_key
       and stripe_charge_id = p_stripe_charge_id
       and kind = 'reversal'
       and source_transfer_id = p_source_transfer_id
       and stripe_object_id = p_stripe_reversal_id
       and amount = p_amount
  ) then
    raise exception 'connect_reversal_idempotency_conflict';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_stripe_invoice_paid(p_stripe_customer_id text, p_stripe_subscription_id text, p_event_id text, p_event_created_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_account public.billing_accounts%rowtype;
  v_resolved integer;
begin
  if p_stripe_customer_id is null or p_stripe_customer_id !~ '^cus_'
     or p_stripe_subscription_id is null or p_stripe_subscription_id !~ '^sub_'
     or p_event_id is null or btrim(p_event_id) = '' or p_event_created_at is null then
    raise exception 'invalid_paid_invoice_event';
  end if;

  select *
    into v_account
    from public.billing_accounts
   where stripe_customer_id = p_stripe_customer_id
   for update;

  if not found then
    raise exception 'billing_account_missing';
  end if;
  if v_account.anonymized_at is not null then
    return jsonb_build_object('status', 'ignored_anonymized');
  end if;
  if v_account.stripe_subscription_id is distinct from p_stripe_subscription_id then
    return jsonb_build_object('status', 'ignored_unrelated_subscription');
  end if;
  if v_account.last_paid_invoice_event_at is not null
     and p_event_created_at < v_account.last_paid_invoice_event_at then
    return jsonb_build_object('status', 'ignored_stale_event');
  end if;

  update public.billing_accounts
     set last_paid_invoice_event_id = p_event_id,
         last_paid_invoice_event_at = p_event_created_at,
         access_decision_event_id = case
           when access_decision_at is null or p_event_created_at >= access_decision_at
             then p_event_id
           else access_decision_event_id
         end,
         access_decision_at = greatest(
           coalesce(access_decision_at, '-infinity'::timestamptz),
           p_event_created_at
         )
   where id = v_account.id;

  update public.stripe_access_incidents
     set status = 'resolved',
         blocked_reason = null,
         last_event_id = p_event_id,
         last_event_created_at = p_event_created_at,
         resolved_at = p_event_created_at
   where stripe_customer_id = p_stripe_customer_id
     and incident_kind = 'full_refund'
     and status = 'blocking'
     and last_event_created_at < p_event_created_at;
  get diagnostics v_resolved = row_count;

  perform public.refresh_stripe_access_block(p_stripe_customer_id);
  perform public.refresh_stripe_access_grant(p_stripe_customer_id);

  return jsonb_build_object('status', 'recalculated', 'refunds_resolved', v_resolved);
end;
$function$

CREATE OR REPLACE FUNCTION public.refresh_stripe_access_grant(p_stripe_customer_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_account public.billing_accounts%rowtype;
  v_status text;
  v_access_until timestamptz;
begin
  select *
    into v_account
    from public.billing_accounts
   where stripe_customer_id = p_stripe_customer_id
   for update;

  if not found then
    return;
  end if;

  if v_account.user_id is null or v_account.anonymized_at is not null then
    delete from public.access_grants
     where source = 'stripe' and source_key = p_stripe_customer_id;
    return;
  end if;

  if v_account.access_blocked_reason is not null then
    v_status := 'revoked';
    v_access_until := null;
  elsif v_account.entitlement_eligible
        and v_account.subscription_status = 'active'
        and v_account.current_period_end is not null
        and v_account.current_period_end > now() then
    v_status := 'active';
    v_access_until := v_account.current_period_end;
  elsif v_account.entitlement_eligible
        and v_account.subscription_status = 'past_due'
        and v_account.grace_until is not null
        and v_account.grace_until > now() then
    v_status := 'grace';
    v_access_until := v_account.grace_until;
  else
    v_status := 'revoked';
    v_access_until := null;
  end if;

  insert into public.access_grants (
    user_id, source, source_key, status, access_until, revoked_at
  ) values (
    v_account.user_id,
    'stripe',
    p_stripe_customer_id,
    v_status,
    v_access_until,
    case when v_status = 'revoked' then now() else null end
  )
  on conflict (source, source_key) do update
    set user_id = excluded.user_id,
        status = excluded.status,
        access_until = excluded.access_until,
        revoked_at = excluded.revoked_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.register_as_partner(p_upline_user_id uuid, p_new_user_name text, p_new_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_contact_id uuid;
  v_parent_id uuid;
begin
  if auth.uid() is null or p_new_user_id is distinct from auth.uid() then
    raise exception 'partner_registration_identity_mismatch';
  end if;
  if not public.has_app_entitlement(auth.uid()) then
    raise exception 'app_entitlement_required';
  end if;
  if p_upline_user_id is null or p_upline_user_id = auth.uid() then
    raise exception 'invalid_upline';
  end if;
  if nullif(btrim(p_new_user_name), '') is null then
    raise exception 'partner_name_required';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('zynergia_partner_graph', 0)
  );

  select s.parent_id
    into v_parent_id
    from public.settings s
   where s.user_id = auth.uid()
   for update;

  if not found or v_parent_id is distinct from p_upline_user_id then
    raise exception 'verified_upline_required';
  end if;
  if not exists (select 1 from public.settings where user_id = p_upline_user_id) then
    raise exception 'upline_not_found';
  end if;
  if exists (
    with recursive ancestors(user_id, parent_id) as (
      select s.user_id, s.parent_id
        from public.settings s
       where s.user_id = p_upline_user_id
      union
      select parent.user_id, parent.parent_id
        from public.settings parent
        join ancestors child on parent.user_id = child.parent_id
       where child.parent_id is not null
    )
    select 1 from ancestors where user_id = auth.uid()
  ) then
    raise exception 'partner_cycle_detected';
  end if;
  if exists (
    select 1 from public.partners
     where user_id = p_upline_user_id and partner_user_id = auth.uid()
  ) then
    return;
  end if;

  insert into public.contacts (
    user_id, full_name, contact_type, phone, country_code, notes
  ) values (
    p_upline_user_id, btrim(p_new_user_name), 'partner', '', '+52',
    'Agregado por código de invitación'
  ) returning id into v_contact_id;

  insert into public.partners (
    user_id, contact_id, partner_user_id, start_date, fast_start_deadline,
    fast_start_status, fase_actual, qteam_completed, fs_level1_completed,
    fs_level2_completed, xteam_completed
  ) values (
    p_upline_user_id, v_contact_id, auth.uid(), current_date, current_date + 120,
    'activo', 1, false, false, false, false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reserve_checkout_operation(p_user_id uuid, p_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_account public.billing_accounts%rowtype;
begin
  if p_user_id is null or p_operation_id is null then
    raise exception 'invalid_checkout_operation';
  end if;

  select *
    into v_account
    from public.billing_accounts
   where user_id = p_user_id and anonymized_at is null
   for update;

  if not found then
    raise exception 'billing_account_missing';
  end if;
  if v_account.operation_id = p_operation_id then
    return jsonb_build_object('status', 'reserved');
  end if;
  if v_account.operation_id is not null and v_account.operation_expires_at > now() then
    return jsonb_build_object('status', 'conflict');
  end if;

  update public.billing_accounts
     set operation_id = p_operation_id,
         operation_expires_at = now() + interval '24 hours'
   where id = v_account.id;

  return jsonb_build_object('status', 'reserved');
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.schedule_account_deletion(p_request_id uuid, p_execute_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rows integer;
begin
  if p_execute_at is null then
    raise exception 'deletion_execute_at_required';
  end if;

  update public.account_deletion_requests
     set status = 'scheduled',
         execute_at = p_execute_at,
         locked_at = null,
         failure_code = null
   where id = p_request_id
     and status in ('scheduling', 'processing', 'failed', 'scheduled');
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    raise exception 'deletion_request_not_schedulable';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_fast_start_date(p_started_at date)
 RETURNS date
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_rows integer;
begin
  if v_user_id is null then
    raise exception 'authentication_required';
  end if;
  if not public.has_app_entitlement(v_user_id) then
    raise exception 'app_entitlement_required';
  end if;
  if p_started_at is null then
    raise exception 'fast_start_date_required';
  end if;
  if p_started_at > current_date then
    raise exception 'fast_start_date_in_future';
  end if;

  update public.settings
     set fast_start_started_at = p_started_at
   where user_id = v_user_id;
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    raise exception 'settings_row_missing';
  end if;

  return p_started_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_parent_id(p_child_user_id uuid, p_parent_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or p_parent_user_id is distinct from auth.uid() then
    raise exception 'parent_identity_mismatch';
  end if;
  if not public.has_app_entitlement(auth.uid()) then
    raise exception 'app_entitlement_required';
  end if;
  if p_child_user_id is null or p_child_user_id = auth.uid() then
    raise exception 'invalid_child';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended('zynergia_partner_graph', 0)
  );
  if not exists (
    select 1 from public.partners p
     where p.user_id = auth.uid() and p.partner_user_id = p_child_user_id
  ) then
    raise exception 'verified_partner_link_required';
  end if;

  update public.settings
     set parent_id = auth.uid()
   where user_id = p_child_user_id
     and (parent_id is null or parent_id = auth.uid());
  if not found then
    raise exception 'child_already_has_parent';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_stripe_connect_charge_snapshot(p_stripe_charge_id text, p_stripe_invoice_id text, p_stripe_payment_intent_id text, p_stripe_customer_id text, p_stripe_subscription_id text, p_stripe_original_transfer_id text, p_stripe_destination_account_id text, p_currency text, p_charge_amount bigint, p_original_transfer_amount bigint, p_original_transfer_amount_reversed bigint, p_original_transfer_created_at timestamp with time zone, p_effective_refund_amount bigint, p_financial_dispute_amount bigint, p_desired_clawback_amount bigint, p_disputes jsonb, p_event_id text, p_event_created_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_existing public.stripe_connect_charges%rowtype;
  v_dispute jsonb;
  v_calculated_disputes bigint := 0;
  v_status text;
  v_blocking boolean;
begin
  if p_stripe_charge_id !~ '^ch_' or p_stripe_invoice_id !~ '^in_'
     or p_stripe_payment_intent_id !~ '^pi_' or p_stripe_customer_id !~ '^cus_'
     or p_stripe_subscription_id !~ '^sub_' or p_stripe_original_transfer_id !~ '^tr_'
     or p_stripe_destination_account_id !~ '^acct_' or p_currency !~ '^[a-z]{3}$'
     or p_charge_amount <= 0 or p_original_transfer_amount <= 0
     or p_original_transfer_amount > p_charge_amount
     or p_original_transfer_amount_reversed < 0
     or p_original_transfer_amount_reversed > p_original_transfer_amount
     or p_effective_refund_amount < 0 or p_effective_refund_amount > p_charge_amount
     or p_financial_dispute_amount < 0 or p_financial_dispute_amount > p_charge_amount
     or p_desired_clawback_amount < 0 or p_desired_clawback_amount > p_original_transfer_amount
     or p_original_transfer_created_at is null or p_event_id is null or p_event_created_at is null
     or jsonb_typeof(p_disputes) is distinct from 'array' then
    raise exception 'invalid_connect_charge_snapshot';
  end if;

  for v_dispute in select value from jsonb_array_elements(p_disputes)
  loop
    v_status := v_dispute->>'status';
    -- Access is blocked for open disputes in a separate canonical incident.
    -- Financial clawback waits for `lost` so US -> MX cross-border reversals
    -- are not attempted while Stripe can prohibit them.
    v_blocking := v_status = 'lost';
    if coalesce(v_dispute->>'id', '') !~ '^(dp_|du_)'
       or coalesce((v_dispute->>'amount')::bigint, 0) <= 0
       or v_dispute->>'currency' is distinct from p_currency
       or v_status not in (
         'warning_needs_response', 'warning_under_review', 'warning_closed',
         'needs_response', 'under_review', 'won', 'lost', 'prevented'
       ) then
      raise exception 'invalid_connect_dispute_snapshot';
    end if;
    if v_blocking then
      v_calculated_disputes := least(
        p_charge_amount,
        v_calculated_disputes + (v_dispute->>'amount')::bigint
      );
    end if;
  end loop;

  if v_calculated_disputes <> p_financial_dispute_amount then
    raise exception 'connect_dispute_total_mismatch';
  end if;
  if p_desired_clawback_amount <> round(
    p_original_transfer_amount::numeric *
    least(p_charge_amount, p_effective_refund_amount + p_financial_dispute_amount)::numeric /
    p_charge_amount::numeric
  )::bigint then
    raise exception 'connect_clawback_total_mismatch';
  end if;

  select * into v_existing
    from public.stripe_connect_charges
   where stripe_charge_id = p_stripe_charge_id
   for update;
  if found and (
    v_existing.stripe_invoice_id is distinct from p_stripe_invoice_id
    or v_existing.stripe_payment_intent_id is distinct from p_stripe_payment_intent_id
    or v_existing.stripe_customer_id is distinct from p_stripe_customer_id
    or v_existing.stripe_subscription_id is distinct from p_stripe_subscription_id
    or v_existing.stripe_original_transfer_id is distinct from p_stripe_original_transfer_id
    or v_existing.stripe_destination_account_id is distinct from p_stripe_destination_account_id
    or v_existing.currency is distinct from p_currency
    or v_existing.charge_amount is distinct from p_charge_amount
    or v_existing.original_transfer_amount is distinct from p_original_transfer_amount
  ) then
    raise exception 'connect_charge_identity_mismatch';
  end if;

  insert into public.stripe_connect_charges (
    stripe_charge_id, stripe_invoice_id, stripe_payment_intent_id,
    stripe_customer_id, stripe_subscription_id, stripe_original_transfer_id,
    stripe_destination_account_id, currency, charge_amount, original_transfer_amount,
    effective_refund_amount, financial_dispute_amount, desired_clawback_amount,
    reconciliation_status, last_event_id, last_event_created_at, last_error
  ) values (
    p_stripe_charge_id, p_stripe_invoice_id, p_stripe_payment_intent_id,
    p_stripe_customer_id, p_stripe_subscription_id, p_stripe_original_transfer_id,
    p_stripe_destination_account_id, p_currency, p_charge_amount, p_original_transfer_amount,
    p_effective_refund_amount, p_financial_dispute_amount, p_desired_clawback_amount,
    'pending', p_event_id, p_event_created_at, null
  ) on conflict (stripe_charge_id) do update
    set stripe_invoice_id = excluded.stripe_invoice_id,
        stripe_payment_intent_id = excluded.stripe_payment_intent_id,
        stripe_customer_id = excluded.stripe_customer_id,
        stripe_subscription_id = excluded.stripe_subscription_id,
        stripe_original_transfer_id = excluded.stripe_original_transfer_id,
        stripe_destination_account_id = excluded.stripe_destination_account_id,
        currency = excluded.currency,
        charge_amount = excluded.charge_amount,
        original_transfer_amount = excluded.original_transfer_amount,
        effective_refund_amount = excluded.effective_refund_amount,
        financial_dispute_amount = excluded.financial_dispute_amount,
        desired_clawback_amount = excluded.desired_clawback_amount,
        reconciliation_status = 'pending',
        last_event_id = excluded.last_event_id,
        last_event_created_at = excluded.last_event_created_at,
        last_error = null;

  insert into public.stripe_connect_transfers (
    stripe_transfer_id, stripe_charge_id, kind, amount, amount_reversed,
    currency, stripe_destination_account_id, stripe_created_at, last_seen_at
  ) values (
    p_stripe_original_transfer_id, p_stripe_charge_id, 'original',
    p_original_transfer_amount, p_original_transfer_amount_reversed,
    p_currency, p_stripe_destination_account_id, p_original_transfer_created_at, now()
  ) on conflict (stripe_transfer_id) do update
    set amount = excluded.amount,
        amount_reversed = excluded.amount_reversed,
        currency = excluded.currency,
        stripe_destination_account_id = excluded.stripe_destination_account_id,
        last_seen_at = now();

  delete from public.stripe_connect_disputes d
   where d.stripe_charge_id = p_stripe_charge_id
     and not exists (
       select 1 from jsonb_array_elements(p_disputes) item
        where item->>'id' = d.stripe_dispute_id
     );

  for v_dispute in select value from jsonb_array_elements(p_disputes)
  loop
    v_status := v_dispute->>'status';
    v_blocking := v_status = 'lost';
    insert into public.stripe_connect_disputes (
      stripe_dispute_id, stripe_charge_id, amount, currency, status,
      financially_blocking, last_event_id, last_event_created_at
    ) values (
      v_dispute->>'id', p_stripe_charge_id, (v_dispute->>'amount')::bigint,
      p_currency, v_status, v_blocking, p_event_id, p_event_created_at
    ) on conflict (stripe_dispute_id) do update
      set stripe_charge_id = excluded.stripe_charge_id,
          amount = excluded.amount,
          currency = excluded.currency,
          status = excluded.status,
          financially_blocking = excluded.financially_blocking,
          last_event_id = excluded.last_event_id,
          last_event_created_at = excluded.last_event_created_at;
  end loop;

  return jsonb_build_object(
    'status', 'synced',
    'state', public.get_stripe_connect_charge_state(p_stripe_charge_id)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_stripe_connect_transfer_snapshot(p_stripe_charge_id text, p_stripe_transfer_id text, p_kind text, p_amount bigint, p_amount_reversed bigint, p_currency text, p_destination_account_id text, p_transfer_created_at timestamp with time zone, p_reversals jsonb, p_event_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_charge public.stripe_connect_charges%rowtype;
  v_existing public.stripe_connect_transfers%rowtype;
  v_reversal jsonb;
  v_reversal_total bigint := 0;
begin
  select * into v_charge
    from public.stripe_connect_charges
   where stripe_charge_id = p_stripe_charge_id
   for update;
  if not found then raise exception 'connect_charge_missing'; end if;
  if p_stripe_transfer_id !~ '^tr_' or p_kind not in ('original', 'restoration')
     or p_amount <= 0 or p_amount_reversed < 0 or p_amount_reversed > p_amount
     or p_currency is distinct from v_charge.currency
     or p_destination_account_id is distinct from v_charge.stripe_destination_account_id
     or p_transfer_created_at is null or p_event_id is null
     or jsonb_typeof(p_reversals) is distinct from 'array' then
    raise exception 'invalid_connect_transfer_snapshot';
  end if;
  if p_kind = 'original' and p_stripe_transfer_id is distinct from v_charge.stripe_original_transfer_id then
    raise exception 'connect_original_transfer_mismatch';
  end if;

  select * into v_existing
    from public.stripe_connect_transfers
   where stripe_transfer_id = p_stripe_transfer_id;
  if found and (
    v_existing.stripe_charge_id is distinct from p_stripe_charge_id
    or v_existing.kind is distinct from p_kind
    or v_existing.amount is distinct from p_amount
    or v_existing.currency is distinct from p_currency
    or v_existing.stripe_destination_account_id is distinct from p_destination_account_id
    or v_existing.stripe_created_at is distinct from p_transfer_created_at
  ) then
    raise exception 'connect_transfer_identity_mismatch';
  end if;

  insert into public.stripe_connect_transfers (
    stripe_transfer_id, stripe_charge_id, kind, amount, amount_reversed,
    currency, stripe_destination_account_id, stripe_created_at, last_seen_at
  ) values (
    p_stripe_transfer_id, p_stripe_charge_id, p_kind, p_amount, p_amount_reversed,
    p_currency, p_destination_account_id, p_transfer_created_at, now()
  ) on conflict (stripe_transfer_id) do update
    set amount = excluded.amount,
        amount_reversed = excluded.amount_reversed,
        last_seen_at = now();

  for v_reversal in select value from jsonb_array_elements(p_reversals)
  loop
    if coalesce(v_reversal->>'id', '') !~ '^trr_'
       or coalesce((v_reversal->>'amount')::bigint, 0) <= 0
       or v_reversal->>'currency' is distinct from p_currency then
      raise exception 'invalid_connect_reversal_snapshot';
    end if;
    v_reversal_total := v_reversal_total + (v_reversal->>'amount')::bigint;
    insert into public.stripe_connect_adjustments (
      operation_key, stripe_charge_id, kind, source_transfer_id,
      stripe_object_id, amount, event_id
    ) values (
      'stripe:' || (v_reversal->>'id'), p_stripe_charge_id, 'reversal',
      p_stripe_transfer_id, v_reversal->>'id', (v_reversal->>'amount')::bigint, p_event_id
    ) on conflict (stripe_object_id) do nothing;
  end loop;

  if v_reversal_total <> p_amount_reversed then
    raise exception 'connect_reversal_total_mismatch';
  end if;

  return public.get_stripe_connect_charge_state(p_stripe_charge_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.zynergia_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$
